// Animation Library — 1000+ declarative entries, no imperative code.
// Each entry is consumed by animationMatcher.js + Draw.jsx renderer.
// ageVariants keys: young (2-4), mid (5-7), older (8-10)

const mk = (id,tags,scene,label,yP,yT,yTx,mP,mT,mTx,oP,oT,oTx,eY={},eM={},eO={}) => ({
  id, tags, scene, label,
  ageVariants:{
    young:{ primitive:yP, trail:yT, textPop:yTx, ...eY },
    mid:  { primitive:mP, trail:mT, textPop:mTx, ...eM },
    older:{ primitive:oP, trail:oT, textPop:oTx, screenShake:true, ...eO },
  }
})

